  "_sourcesStr": "Apple Music MY、Astro",
  "description": "Siti Gema Bumantara专辑（Siti Nurhaliza《Gema Bumantara》（回响婆罗洲））是近期马来西亚市场演出娱乐领域的焦点事件。 国民歌后Legacy 30专辑，Batik风。 该活动属于演唱会/综艺类热点，在年轻群体中传播速度极快，周边T恤需求通常集中在活动前后2-3周的时间窗口内。 本条热点汇聚了2个数据来源交叉验证。 当前热度达★★★★级，属高潜力爆款候选。 建议采用文字+图案组合款，兼顾口号传播与视觉识别效果。 该话题风险较低，可放心开发设计。 该热点具有泰马本地媒体来源支撑，属于本土原生热度，跨境印花溢价潜力较高。"
